#include <gtest/gtest.h>

#include <limits>

#include "x-platform/types.h"

/**
 * ssize_t must be signed since it is expected to hold the -1 sentinel value
 * that several of the system calls return to indicate an error.
 */
TEST(XPlatformTypes, SsizeTIsSigned) {
  ASSERT_TRUE(std::numeric_limits<ssize_t>::is_signed);

  constexpr ssize_t sentinel = -1;
  ASSERT_EQ(sentinel, -1);
}

/**
 * ssize_t must be able to accommodate at least the range of an int.
 */
TEST(XPlatformTypes, SsizeTIntCompatibility) {
  ASSERT_GE(std::numeric_limits<ssize_t>::max(),
            std::numeric_limits<int>::max());
  ASSERT_LE(std::numeric_limits<ssize_t>::min(),
            std::numeric_limits<int>::min());
}

/**
 * ssize_t must be able to accommodate at least the range of a long int.
 */
TEST(XPlatformTypes, SsizeTLongIntCompatibility) {
  ASSERT_GE(std::numeric_limits<ssize_t>::max(),
            std::numeric_limits<long int>::max());  // NOLINT(runtime/int)
  ASSERT_LE(std::numeric_limits<ssize_t>::min(),
            std::numeric_limits<long int>::min());  // NOLINT(runtime/int)
}

